## ✨ 설명
```ruby
/*
* 탐색 문제 - 이번엔 bfs로 해결함 (dfs도 가능)
* 탐색을 하면서 공기에 맞닿은 1겹의 치즈를 표시만 해둔다(-1로)
* 탐색 1트 끝나고 체크해둔 부분을 0으로 바꿔버린다.
* 이후 죄다 0 될 때까지 반복
*/


main() {
    input 값 저장
    
    맵에 치즈가 없을 때 까지 반복
        (0, 0) 큐 방문
        큐가 빌 때까지 반복
            큐 가장 윗 요소 뽑기(좌표)
            현재 좌표 기준 4 방위 좌표에 대해 반복
                해당 좌표가 범위 밖이거나, 방문한 경우는 스킵
                만약 해당 좌표가 치즈라면?
                    (-1)로 일단 체크해둠
                    치즈 갯수++(ans++)
                치즈가 아니라 공기라면?
                    방문처리 후 해당 좌표 큐에 넣기
            
        (-1)로 체크해둔 치즈를 공기(0)로 바꾸기
        제거한 치즈 겹 수++(cnt++)
    
    정답 출력(cnt, ans)
}

chk() {
    맵에 치즈가 하나라도 있으면 1 반환
}
```

## 📚 전체 코드
[코드](https://github.com/ehdgnsl01/Tools_Algorithm_Study/pull/17/files#diff-54f91adab99888a36337bfb9e19a428e1fe2dac916b4f8b9eaac26a8a8b3811f)
```cpp
#include <bits/stdc++.h>
using namespace std;
int n, m, arr[104][104], vst[104][104], dx[4] = {-1, 0, 1, 0}, dy[4] = {0, 1, 0, -1}, x, y, xx, yy, cnt, ans;
queue<pair<int, int>> q;
int chk() {
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (arr[i][j]) return 1;
    return 0;
}
int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> arr[i][j];
    while (chk()) {
        ans = 0;
        vst[0][0] = 1;
        q.push({0, 0});
        while (q.size()) {
            tie(y, x) = q.front(); q.pop();
            for (int i = 0; i < 4; i ++) {
                xx = x + dx[i];
                yy = y + dy[i];
                if (xx < 0 || yy < 0 || xx >= m || yy >= n || vst[yy][xx]) continue;
                if (arr[yy][xx] == 1) {
                    arr[yy][xx] = -1;
                    ans++;
                }
                else if (arr[yy][xx] == 0){
                    vst[yy][xx] = 1;
                    q.push({yy, xx});
                }
            }
        }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if (arr[i][j] == -1) arr[i][j] = 0;
            }
        memset(vst, 0, sizeof(vst));
        cnt++;
    }
    cout << cnt << "\n" << ans;
}
```

